WITH row_rank_1 AS (
    SELECT DISTINCT ON (rr.HK_CITY) rr.HK_CITY, rr.city_name, rr.LOAD_DATETIME, rr.RECORD_SOURCE
    FROM "krisha_dwh"."marts_dv"."stg_dv_listings" AS rr
    WHERE rr.HK_CITY IS NOT NULL
    ORDER BY rr.HK_CITY, rr.LOAD_DATETIME
),

records_to_insert AS (
    SELECT a.HK_CITY, a.city_name, a.LOAD_DATETIME, a.RECORD_SOURCE
    FROM row_rank_1 AS a
    LEFT JOIN "krisha_dwh"."marts_dv"."hub_city" AS d
    ON a.HK_CITY = d.HK_CITY
    WHERE d.HK_CITY IS NULL
)

SELECT * FROM records_to_insert